MIGRATE_CONTENT_CACHE_PATH = Path(__file__).parent.parent / "data" / "cache" / "migrate_content.json"


def load_migrate_content_cache() -> dict:
    """Expanded migration-guide content generated by migrate_content_generator.py,
    keyed by '{prop_key}-to-{oss_key}'. Returns {} if the cache doesn't exist yet
    (e.g. before the generator has been run), in which case build_migration_page()
    falls back to the original short-form content."""
    if MIGRATE_CONTENT_CACHE_PATH.exists():
        with open(MIGRATE_CONTENT_CACHE_PATH) as f:
            return json.load(f)
    return {}


