def build_related_section(current_slug: str, current_prop: str, current_oss: str,
                           all_comparisons: List[Dict]) -> str:
    related = []
    for c in all_comparisons:
        if c['slug'] == current_slug:
            continue
        if (c.get('proprietary_tool') == current_prop or
            c.get('oss_tool') == current_oss or
            c.get('proprietary_tool') == current_oss or
            c.get('oss_tool') == current_prop):
            related.append(c)
    if not related:
        return ''
    links = ''.join(
        f'<a class="related-link" href="../{c["slug"]}/">{c["title"]}</a>'
        for c in related[:6]
    )
    return f"""
  <div class="card">
    <h2 style="font-size:1rem; font-weight:700; color:#1F5C99; margin-bottom:0.75rem;">🔗 Related Comparisons</h2>
    <div class="related-grid">{links}</div>
  </div>"""


def load_momentum(cache_dir: str = '.cache/publish') -> list:
    momentum_path = Path(cache_dir) / 'momentum.json'
    if not momentum_path.exists():
        return []
    try:
        with open(momentum_path) as f:
            return json.load(f)
    except Exception:
        return []


def build_trending_section(momentum: list) -> str:
    if not momentum:
        return ''
    top = momentum[:6]
    cards = ''
    for m in top:
        delta     = m.get('weekly_rate', m.get('delta', 0))
        stars_now = m.get('stars_now', 0)
        name      = m.get('oss_name', '')
        prop      = m.get('prop_name', '')
        slug      = m.get('slug', '')
        github    = m.get('oss_github', '')

        def fmt_stars(n):
            if n >= 1000:
                return f"{n/1000:.1f}k"
            return str(n)

        delta_str = f"+{fmt_stars(delta)}"
        bar_width = min(100, max(10, int(delta / max(top[0].get('weekly_rate', 1), 1) * 100)))

        cards += f"""
      <div class="trend-card">
        <div class="trend-header">
          <div class="trend-name">{name}</div>
          <div class="trend-delta">{delta_str} ⭐/wk</div>
        </div>
        <div class="trend-bar-wrap">
          <div class="trend-bar" style="width:{bar_width}%"></div>
        </div>
        <div class="trend-meta">
          <span class="trend-total">⭐ {fmt_stars(stars_now)} total</span>
          {f'<span class="trend-prop">alt to {prop}</span>' if prop else ''}
        </div>
        <div class="trend-links">
          {f'<a href="{slug}/" class="trend-link">Compare →</a>' if slug else ''}
          {f'<a href="https://github.com/{github}" target="_blank" rel="noopener" class="trend-gh">GitHub ↗</a>' if github else ''}
        </div>
      </div>"""

    return f"""
<div class="trending-section">
  <div class="trending-inner">
    <div class="trending-header">
      <div class="trending-title">📈 Trending This Week</div>
      <div class="trending-sub">Open source tools gaining the most GitHub stars — updated daily</div>
    </div>
    <div class="trending-grid">{cards}
    </div>
  </div>
</div>"""


def build_sitemap(all_comparisons: List[Dict], site_dir: str, categories: List[str]):
    today = datetime.utcnow().strftime('%Y-%m-%d')
    urls = [f'  <url><loc>{SITE_BASE_URL}/</loc><changefreq>daily</changefreq><priority>1.0</priority><lastmod>{today}</lastmod></url>']
    for cat in categories:
        urls.append(f'  <url><loc>{SITE_BASE_URL}/{cat}/</loc><changefreq>weekly</changefreq><priority>0.7</priority><lastmod>{today}</lastmod></url>')
    for comp in all_comparisons:
        urls.append(f'  <url><loc>{SITE_BASE_URL}/{comp["slug"]}/</loc><changefreq>weekly</changefreq><priority>0.9</priority><lastmod>{today}</lastmod></url>')
    for comp in all_comparisons:
        prop_key = comp.get('proprietary_key', '')
        oss_key  = comp.get('oss_key', '')
        if prop_key and oss_key:
            urls.append(f'  <url><loc>{SITE_BASE_URL}/migrate-{prop_key}-to-{oss_key}/</loc><changefreq>monthly</changefreq><priority>0.8</priority><lastmod>{today}</lastmod></url>')
    seen_props = set()
    for comp in all_comparisons:
        prop_key = comp.get('proprietary_key', '')
        if prop_key and prop_key not in seen_props:
            seen_props.add(prop_key)
            urls.append(f'  <url><loc>{SITE_BASE_URL}/alternatives-to-{prop_key}/</loc><changefreq>weekly</changefreq><priority>0.9</priority><lastmod>{today}</lastmod></url>')
    for page in ['privacy', 'savings-calculator', 'changelog', 'about', 'contact', 'stats', 'quiz', 'blog']:
        urls.append(f'  <url><loc>{SITE_BASE_URL}/{page}/</loc><changefreq>monthly</changefreq><priority>0.6</priority><lastmod>{today}</lastmod></url>')
    urls.append(f'  <url><loc>{SITE_BASE_URL}/price-hikes/</loc><changefreq>weekly</changefreq><priority>0.8</priority><lastmod>{today}</lastmod></url>')
    urls.append(f'  <url><loc>{SITE_BASE_URL}/infographics/</loc><changefreq>monthly</changefreq><priority>0.8</priority><lastmod>{today}</lastmod></url>')
    urls.append(f'  <url><loc>{SITE_BASE_URL}/stack-builder/</loc><changefreq>monthly</changefreq><priority>0.9</priority><lastmod>{today}</lastmod></url>')
    urls.append(f'  <url><loc>{SITE_BASE_URL}/logo-api/</loc><changefreq>monthly</changefreq><priority>0.9</priority><lastmod>{today}</lastmod></url>')
    for ind_slug in ['open-source-tools-for-startups', 'open-source-tools-for-developers', 'open-source-tools-for-remote-teams']:
        urls.append(f'  <url><loc>{SITE_BASE_URL}/{ind_slug}/</loc><changefreq>monthly</changefreq><priority>0.8</priority><lastmod>{today}</lastmod></url>')
    blog_slugs = [
        'why-teams-are-switching-from-figma-to-penpot',
        'true-cost-of-slack-for-growing-teams',
        'jira-alternatives-for-startups',
        'self-hosting-notion-alternative-guide',
        'open-source-design-tools-comparison',
        'github-alternatives-self-hosted',
        'how-to-cut-saas-costs-without-losing-productivity',
        'docusign-vs-docuseal-esignature-comparison',
    ]
    for bs in blog_slugs:
        urls.append(f'  <url><loc>{SITE_BASE_URL}/blog/{bs}/</loc><changefreq>weekly</changefreq><priority>0.8</priority><lastmod>{today}</lastmod></url>')
    sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    sitemap += '\n'.join(urls) + '\n</urlset>'
    with open(Path(site_dir) / 'sitemap.xml', 'w') as f:
        f.write(sitemap)
    logger.info(f"   🗺️  sitemap.xml ({len(all_comparisons) + len(categories) + 2} URLs)")


